INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q697722', 'Battle of Pressburg', 'The Battle of Pressburg (German: Schlacht von Pressburg), or Battle of Pozsony (Hungarian: Pozsonyi csata), or Battle of Bratislava (Slovak: bitka pri Bratislave) was a three-day-long battle fought between 4 and 6 July 907, during which the East Francian army, consisting mainly of Bavarian troops led by Margrave Luitpold, was annihilated by Hungarian forces. The exact location of the battle is not known.', 907, 7, 4, NULL, NULL, NULL, 'day', '4 July 907', 61, 'https://en.wikipedia.org/wiki/Battle_of_Pressburg'),
  ('Q181293', 'Battle of Rozgony', 'The Battle of Rozgony or Battle of Rozhanovce was fought between King Charles Robert of Hungary and the family of Palatine Amade Aba on 15 June 1312, on the Rozgony (today Rozhanovce) field. Chronicon Pictum described it as the "most cruel battle since the Mongol invasion of Europe".', 1312, 6, 15, NULL, NULL, NULL, 'day', '15 June 1312', 53, 'https://en.wikipedia.org/wiki/Battle_of_Rozgony'),
  ('Q3277009', 'Battle of Trnava', 'The Battle of Trnava or Battle of Nagyszombat took place during the Hussite Wars between the Hussites and the Hungarian-Royalists-Serbian army near Trnava (Nagyszombat) in the Kingdom of Hungary (today in Slovakia). The battle was fought in three phases, on 23, 25 and 28 April 1430 and ended in Hussite victory.', 1430, 4, 28, 1430, 4, 28, 'day', '28 April 1430', 41, 'https://en.wikipedia.org/wiki/Battle_of_Trnava_(1430)'),
  ('Q723957', 'Battle of Humenné', 'The Battle of Humenné (Hungarian: Homonnai csata, Polish: bitwa pod Humiennem or pierwsza odsiecz wiedeńska) took place on 22–23 November 1619 near Humenné (eastern Slovakia) during the first period of the Thirty Years'' War between the Transylvanian army and the joined loyalist Hungarian and Polish forces of Lisowczycy. It was the only battle of that war to involve the Polish–Lithuanian Commonwealth.', 1619, 11, 23, NULL, NULL, NULL, 'day', '23 November 1619', 41, 'https://en.wikipedia.org/wiki/Battle_of_Humenn%C3%A9'),
  ('Q1470965', 'Siege of Érsekújvár', 'The Siege of Érsekújvár, also known as the Siege of Uyvar or the Siege of Neuhäusel, occurred in 1663 when Grand Vizier Fazil Ahmed Pasha, who led the Ottomans, invaded Habsburg Hungary and captured the Hungarian fortress at Érsekújvár (Hungarian: Érsekújvár, German: Neuhäus[e]l, Latin: Novum Castrum, Turkish: Uyvar, modern Nové Zámky in southern Slovakia).', 1663, 9, 13, 1663, 9, 26, 'day', '13 September 1663 – 26 September 1663', 34, 'https://en.wikipedia.org/wiki/Siege_of_%C3%89rsek%C3%BAjv%C3%A1r_(1663)'),
  ('Q1160506', 'Siege of Léva', 'This page is partially a translation of the French version The siege of Léva was fought on 19 July 1664 as part of the Austro-Turkish War (1663–1664), between a Habsburg army led by Jean-Louis Raduit de Souches and an Ottoman army under the command of Ali Pasha. The battle took place near Léva, Kingdom of Hungary (present-day Slovakia) and was a Habsburg victory.', 1664, 7, 19, NULL, NULL, NULL, 'day', '19 July 1664', 39, 'https://en.wikipedia.org/wiki/Siege_of_L%C3%A9va'),
  ('Q694911', 'Battle of Párkány', 'The Battle of Párkány (Turkish: Ciğerdelen Savaşı) was fought between October 7–9, 1683 in the town of Párkány (today: Štúrovo), in the Ottoman Empire, and the area surrounding it as part of the Polish-Ottoman War and the Great Turkish War. The battle was fought in two stages.', 1683, NULL, NULL, 1683, 10, 9, 'year', '1683', 52, 'https://en.wikipedia.org/wiki/Battle_of_P%C3%A1rk%C3%A1ny'),
  ('Q3273985', 'Siege of Érsekújvár', 'The siege of Érsekújvár was fought between July 7 and August 17 of 1685, between the besieging Habsburg army and the Ottoman garrison of Érsekújvár, city in what is today Nové Zámky, Slovakia (Turkish: Uyvar). The Austrian commander, Aeneas de Caprara, invested the city and stormed it on August 17, slaying the entire Ottoman garrison.', 1685, 7, 7, 1685, 8, 17, 'day', '7 July 1685 – 17 August 1685', 41, 'https://en.wikipedia.org/wiki/Siege_of_%C3%89rsek%C3%BAjv%C3%A1r_(1685)'),
  ('Q4871398', 'Battle of Kassa', 'The Battle of Kassa was fought on October 18, 1685, in the city of Kassa in the Kingdom of Hungary (now Košice in Slovakia), between the armies of the Ottoman Empire and of the Holy Roman Empire. The Austrian Commander, Field Marshal Aeneas de Caprara, defeated the Ottoman Army near the city and with this victory regained Habsburg control of which had been lost in 1682 to the Kuruc leader Imre Thököly.', 1685, 10, 18, NULL, NULL, NULL, 'day', '18 October 1685', 37, 'https://en.wikipedia.org/wiki/Battle_of_Kassa'),
  ('Q561512', 'Battle of Blumenau', 'The Battle of Blumenau or Battle of Lamač was the last battle fought in the Austro-Prussian War, on 22 July 1866 (on the day of the conclusion of peace), with the Austrians defending against the Prussian army.', 1866, 7, 22, NULL, NULL, NULL, 'day', '22 July 1866', 48, 'https://en.wikipedia.org/wiki/Battle_of_Blumenau'),
  ('Q686944', 'Černová massacre', 'The Černová massacre (or Černová tragedy, Slovak: Černovská tragédia, Hungarian: Csernovai tragédia or Csernova Affair) was a shooting that took place in Csernova, Kingdom of Hungary (today Černová, part of Ružomberok, Slovakia) on 27 October 1907 in which 15 people were killed and many were wounded after gendarmes fired into a crowd of people gathering for the consecration of the local Catholic church. The shootings sparked protests in European and American press and turned the world''s attention to the treatment of minorities in the Hungarian part of Austria-Hungary.', 1907, 10, 27, NULL, NULL, NULL, 'day', '27 October 1907', 43, 'https://en.wikipedia.org/wiki/%C4%8Cernov%C3%A1_massacre'),
  ('Q1029489', 'candle demonstration', 'The Candle demonstration (Slovak: Sviečková manifestácia) on 25 March 1988 in Bratislava, the capital of Slovakia, was the first mass demonstration since 1969 against the communist regime in Czechoslovakia. The demonstration was organized by Roman Catholic dissent groups asking for religious freedom in Czechoslovakia.', 1988, 3, 25, NULL, NULL, NULL, 'day', '25 March 1988', 51, 'https://en.wikipedia.org/wiki/Candle_demonstration_in_Bratislava'),
  ('Q4179824', 'Slovak disclosure referendum', 'A referendum on the retrospective disclosure of the financial details of large-scale privatisation was held in Slovakia on 22 October 1994. Although approved by 95.9% of those voting, voter turnout was just 20% and the referendum was declared invalid due to insufficient turnout.', 1994, 10, 22, NULL, NULL, NULL, 'day', '22 October 1994', 37, 'https://en.wikipedia.org/wiki/1994_Slovak_disclosure_referendum'),
  ('Q4179816', 'Slovak referendum', 'A referendum was held in Slovakia on 23 May and 24 May 1997. Voters in Slovakia were asked four separate questions: on whether the country should join NATO, whether nuclear weapons should be allowed in Slovakia, whether foreign military bases should be allowed in Slovakia, and whether the President should be elected directly.', 1997, 5, 24, 1997, 5, 24, 'day', '24 May 1997', 37, 'https://en.wikipedia.org/wiki/1997_Slovak_referendum'),
  ('Q4181425', 'Slovak privatisation referendum', 'A referendum on banning the privatisation of strategically important state-owned companies was held in Slovakia on 25 and 26 September 1998. Although approved by 84.3% of those voting, voter turnout was just 44.1% and the referendum was declared invalid due to insufficient turnout.', 1998, 9, 26, 1998, 9, 26, 'day', '26 September 1998', 37, 'https://en.wikipedia.org/wiki/1998_Slovak_privatisation_referendum'),
  ('Q4181441', 'Slovak early parliamentary elections referendum', 'A referendum on holding early parliamentary elections was held in Slovakia on 11 November 2000. Although approved by 95.1% of those voting, voter turnout was just 20% and the referendum was declared invalid due to insufficient turnout.', 2000, 11, 11, NULL, NULL, NULL, 'day', '11 November 2000', 37, 'https://en.wikipedia.org/wiki/2000_Slovak_early_parliamentary_elections_referendum'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q547591', 'Slovak early parliamentary elections referendum, 2004', 'A referendum on holding early parliamentary elections was held in Slovakia on 3 April 2004. Although approved by 87.9% of those voting, voter turnout was just 35.9% and the referendum was declared invalid due to insufficient turnout.', 2004, 4, 3, NULL, NULL, NULL, 'day', '3 April 2004', 39, 'https://en.wikipedia.org/wiki/2004_Slovak_early_parliamentary_elections_referendum'),
  ('Q871885', '2009 European floods', 'The 2009 European floods were a series of natural disasters that took place in June 2009 in Central Europe. Austria, the Czech Republic, Germany, Hungary, Poland, Romania, Serbia, Slovakia and Turkey were all affected.', 2009, NULL, NULL, NULL, NULL, NULL, 'year', '2009', 37, 'https://en.wikipedia.org/wiki/2009_European_floods'),
  ('Q282940', '2010 Central European floods', 'The 2010 Central European floods were a devastating series of weather events which occurred across several Central European countries during May and June 2010. Poland was the worst affected.', 2010, 5, 14, 2010, 6, 9, 'day', '14 May 2010 – 9 June 2010', 50, 'https://en.wikipedia.org/wiki/2010_Central_European_floods'),
  ('Q2672460', 'Slovak political reform referendum', 'A referendum on political reform was held in Slovakia on 18 September 2010, following a successful petition started as a civil activity along with the foundation of Freedom and Solidarity (SaS). the referendum failed to meet the turnout threshold required under the constitution of slovakia, with only 22.8% of the electorate voting—far below the 50% required.', 2010, 9, 18, NULL, NULL, NULL, 'day', '18 September 2010', 41, 'https://en.wikipedia.org/wiki/2010_Slovak_political_reform_referendum'),
  ('Q15991234', 'Treaty Establishing the European Stability Mechanism', 'The Treaty Establishing the European Stability Mechanism was signed by the member states of the eurozone to found the European Stability Mechanism (ESM), an international organisation located in Luxembourg, to act as a permanent source of financial assistance for member states in financial difficulty, with a maximum lending capacity of €500 billion. It replaced two earlier temporary EU funding programmes: the European Financial Stability Facility (EFSF) and the European Financial Stabilisation Mechanism (EFSM).', 2012, 2, 2, NULL, NULL, NULL, 'day', '2 February 2012', 34, 'https://en.wikipedia.org/wiki/Treaty_establishing_the_European_Stability_Mechanism'),
  ('Q13415210', '2013 European floods', 'Extreme flooding in Central Europe began after several days of heavy rain in late May and early June 2013. Flooding and damages primarily affected south and east German states (Thuringia, Saxony, Saxony-Anhalt, Lower Saxony, Bavaria and Baden-Württemberg), western regions of the Czech Republic (Bohemia), and Austria.', 2013, 5, 28, 2013, 6, 5, 'day', '28 May 2013 – 5 June 2013', 53, 'https://en.wikipedia.org/wiki/2013_European_floods'),
  ('Q16879871', '2014 Southeast Europe floods', 'Between 13 and 18 May 2014 a low-pressure cyclone designated Tamara and Yvette affected a large area of Southeastern and Central Europe, causing floods and landslides. Serbia and Bosnia and Herzegovina suffered the greatest damage, as the rain was the heaviest in 120 years of recorded weather measurements.', 2014, 5, 27, 2014, 5, 27, 'day', '27 May 2014', 63, 'https://en.wikipedia.org/wiki/2014_Southeast_Europe_floods'),
  ('Q18601497', 'Slovak same-sex marriage referendum', 'A referendum on banning same-sex marriage was held in Slovakia on 7 February 2015. Critics claimed the referendum was pushed by religious and conservative organisations, aiming to block gay couples from gaining more rights.', 2015, 2, 7, NULL, NULL, NULL, 'day', '7 February 2015', 52, 'https://en.wikipedia.org/wiki/2015_Slovak_same-sex_marriage_referendum'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q115253367', 'Referendum in Slovakia in 2023', 'A constitutional referendum was held in Slovakia on 21 January 2023. Following the 2020 parliamentary election, in which the Direction – Slovak Social Democracy (SMER) was defeated by the Ordinary People and Independent Personalities (OĽaNO), opposition parties initiated a referendum to call a snap election.', 2023, 1, 21, NULL, NULL, NULL, 'day', '21 January 2023', 39, 'https://en.wikipedia.org/wiki/2023_Slovak_constitutional_referendum'),
  ('Q131900840', '2025 Slovak protests', 'Widespread demonstrations, involving tens of thousands of Slovak citizens mobilizing across Slovakia, have been taking place, primarily to protest Prime Minister of Slovakia Robert Fico''s pro-Russia policies. The demonstrations, organized by Peace for Ukraine, have taken place across more than two dozen different areas throughout the country.', 2024, 12, 23, NULL, NULL, NULL, 'day', '23 December 2024', 45, 'https://en.wikipedia.org/wiki/2024%E2%80%932026_Slovak_protests');
